# -*- coding: utf-8 -*-
"""Final four-sprint design batch: 75 source-audited mockups, no native app writes."""
from sprint_common import *
AUDIT=json.loads((HERE/'batch-11-14-source-audit.json').read_text())
BYFILE={r['file']:r for r in AUDIT}
INVENTORY=json.loads((HERE/'screen-inventory.json').read_text())['screens']
IDS={r['file']:r.get('proposalId') for r in INVENTORY if r.get('proposalId')}
def go(file):return IDS.get(file)
def link(text,file,kind='secondary'):
    target=go(file)
    return button(text,to=target,action=None if target else 'batch-next',kind=kind,extra=f'data-label="{e(text)}"')
def v(body,foot=''):return dict(content=body,footer=foot)
def select(label,name,options):return f'<label class="field"><span>{label}</span><select name="{name}">'+''.join(f'<option value="{i}">{e(t)}</option>' for i,t in enumerate(options))+'</select></label>'
def f(label,name,value='',kind='text',required=True):return field(label,name,value,kind=kind,extra=('required ' if required else '')+('maxlength="80" ' if name=='groupName' else '')+('min="2" step="1"' if name=='capacity' else 'min="1" step="0.01"' if kind=='number' else ''))
def memo(label='ملاحظات',name='note',value='',required=False):return textarea(label,name,value,hint='اكتب التفاصيل هنا…',extra='rows="3" maxlength="4000" '+('required' if required else ''))
DEFAULT_CONFIRM='معاينة محلية فقط. لا يتم إرسال بيانات أو دفع أو توقيع أو منح موافقة حقيقية.'
CONFIRM_COPIES={'review-final':'راجع التقدير والتعليق والجمهور والموعد. التقييم النهائي غير قابل للتعديل؛ استلامه لا يعني نشره فورًا. هذه معاينة محلية فقط.', 'student-consent':'الموافقة تخصك وتخص النسخة الحالية فقط. راجع متطلباتك والإفصاحات المختارة. لا يتم إرسال موافقة حقيقية.', 'rental-summary':'راجع المستلم وتاريخ الانتهاء والحجز والفاتورة والإيصال المختارين. المشاركة للعرض فقط، ولا تمنح تحكمًا في العقد أو الدفع. معاينة محلية.', 'group-action':'راجع اختيارك ومشاركتك. قرارك لا يمثل موافقة باقي الأعضاء ولا ينشئ حجزًا أو عقدًا. معاينة محلية.', 'settlement':'راجع نوع البنود ومبالغها. المقترح لا ينفذ رد أموال أو يقرر المسؤولية. معاينة محلية فقط.'}
def form(body,label='حفظ التغييرات',action='save',unknown=False):
    return f'<form data-form="batch-form" data-kind="{action}" data-review-copy="{e(CONFIRM_COPIES.get(action,DEFAULT_CONFIRM))}">{body}<button type="submit" class="primary wide" data-label="{label}">{label}</button></form>'
def ack(text='راجعت التفاصيل وأوافق على المتابعة.',name='ack'):return f'<label class="ack"><input type="checkbox" name="{name}" data-batch-ack>{text}</label>'
def action(text,kind='secondary',sensitive=False,label=''):
    return button(text,action='batch-confirm' if sensitive else 'batch-preview',kind=kind+' wide',extra=f'data-label="{e(label or text)}"')
def metric(value,label):return f'<div class="stat"><b>{value}</b><small>{label}</small></div>'
def metrics(items):return '<div class="stat-grid">'+''.join(metric(a,b) for a,b in items)+'</div>'
def steps(current,total=3):return f'<div class="step-caption"><span>خطوة {current} من {total}</span><span>بيانات توضيحية</span></div><div class="steps">'+''.join(f'<span class="{"done" if i<current else ""}"></span>' for i in range(total))+'</div>'
def property_block():return compact_property()
def card(title,sub='',status='',target=None,meta=(),action_label='عرض التفاصيل'):
    return panel((badge(status,'warning' if any(x in status for x in ['انتظار','مراجعة','تحقق','معالجة','تحتاج']) else 'info' if any(x in status for x in ['غير معروف','منته','مغلق']) else '') if status else '')+f'<h3 class="batch-card-title">{title}</h3>'+ (f'<p class="small">{sub}</p>' if sub else '')+(summary(meta) if meta else '')+(link(action_label,target) if target else ''))
def list_cards(items):return ''.join(card(**x) for x in items)
def bars():return '<div class="mini-bars" role="img" aria-label="اتجاهات توضيحية لآخر أسبوع">'+''.join(f'<span style="--bar:{h}%"><i></i><small>{d}</small></span>' for h,d in zip([34,48,42,67,53,82,72],['أحد','إثنين','ثلاثاء','أربعاء','خميس','جمعة','سبت']))+'</div>'
def days(action_name='batch-day'):
    return '<div class="day-grid">'+''.join(button(f'<small>{d}</small><strong>{n}</strong>',action=action_name,kind='day',extra=f'data-index="{i}" aria-pressed="{str(i==0).lower()}"') for i,(d,n) in enumerate([('الإثنين','٢٦'),('الثلاثاء','٢٧'),('الأربعاء','٢٨'),('الخميس','٢٩')]))+'</div>'
def media_art(caption='غرفة المعيشة',capture=False):
    return f'<div class="batch-media"><img src="{PHOTOS[0]}" alt="صورة عقار توضيحية">'+('<div class="capture-reticle"></div>' if capture else '')+f'<span class="media-caption">{caption}</span></div>'
def thread(messages):return '<div class="batch-thread">'+''.join(f'<div class="bubble {"outgoing" if i%2==0 else "incoming"}">{text}<small>نص توضيحي · داخل المعاينة</small></div>' for i,text in enumerate(messages))+'</div>'
def readonly(text):return note(text,'info','lock')
SCREENS=[]
def add(file,name,en,body,behavior,kind='detail',back=None,refs=None,variants=None,hero=None,chrome='standard',states=(),footer_html=''):
    rec=BYFILE[file];sid=rec['proposalId'];deps=rec['dependencies']
    s=dict(id=sid,name=name,english=en,source=rec['source'],sha256=rec['sha256'],localeKeys=rec['localeKeys'],dependencies=deps,group={11:'الطلاب وحساب الشركة',12:'تشغيل الشركات والمنافسات',13:'حزم السكن والمعيشة',14:'الانتقال والتنفيذ'}[rec['sprint']],back=go(back) if back else 'S220',content=body,footer=footer_html,variants=variants or {},behavior=behavior,kind=kind,requiredStates=list(dict.fromkeys(['loading','error']+(['empty'] if kind in ['list','hub'] else [])+(['invalid','dirty','saving','unknown-outcome'] if kind in ['form','action','payment','signing'] else ['stale','restricted'])+['stale','restricted']+list(states))),visualReference=refs or (['S17','S20'] if kind in ['form','action'] else ['S18','S19']),sprint=rec['sprint'],chrome=chrome)
    s['reviewGate']='هذه هي الدفعة الأخيرة من المقترح. كل التفاعلات محلية، والمقترح كامل جاهز لمراجعتك.'
    if hero:s['hero']=hero
    SCREENS.append(s)
    return s

def dated(label='التاريخ',name='date',value='2026-12-01'):return f(label,name,value,'date')
def dates():return '<div class="field-pair">'+dated('البداية','start','2026-12-01')+dated('النهاية · غير مشمولة','end','2027-07-01')+'</div>'
def person(name,sub='عضو في المجموعة'):return row(name,sub,action='batch-preview',symbol='user')
def state_button(text,state,kind='secondary wide'):return button(text,action='final-state',kind=kind,extra=f'data-variant="{state}"')
def context(title='شركة النور · مثال',sub='مساحة الشركة المختارة'):return panel('<h3>'+title+'</h3><p class="small">'+sub+'</p>')
def plan_summary():return panel(badge('نسخة ٣ · تحتاج مراجعة','warning')+'<h3 class="batch-card-title">خطة الفصل الدراسي</h3>'+summary([('الفترة','ديسمبر – يوليو'),('المشاركون','٣ طلاب'),('الميزانية','٣٬٠٠٠–٤٬٠٠٠ ج.م للفرد')]))
def monthly():return '<p class="small">مبالغ شهرية توضيحية · كل التواريخ بتوقيت القاهرة.</p>'
def evidence():return section('المرفقات',action('معاينة مرفق توضيحي')+'<p class="small">لم يتم اختيار ملفات من الجهاز أو رفعها.</p>')
def planning():return note('هذه خطة للمراجعة فقط؛ لا تحجز عقارًا ولا تنشئ التزامًا ماليًا.','info','file')
def package_summary():return panel(badge('بانتظار الموافقات','warning')+'<h3 class="batch-card-title">حزمة سكن الجامعة</h3>'+summary([('التخصيصات','٣ أفراد · لكل شخص اختياره'),('الموافقات','٢ من ٣'),('النسخة','٣ · مثال')]))
def own_terms():return summary([('تخصيصي','غرفة ١ · شقة المعادي'),('الإيجار الشهري','٣٬٠٠٠ ج.م'),('التأمين','٣٬٠٠٠ ج.م'),('الفترة','ديسمبر – يوليو')])
def job_status(title='تشغيل البحث',status='قيد المعالجة'):
    return panel(badge(status,'warning')+'<h3 class="batch-card-title">'+title+'</h3><div class="coverage-meter"><span style="width:55%"></span></div><p class="small">الحالة التوضيحية تُحدّث من سجل المهمة.</p>')
CONFIRM_COPIES.update({'execution':'راجع التخصيص والنسخة والسياسة. هذه تجربة تنفيذ محلية فقط؛ لا يتم دفع أموال أو توقيع أو تغيير السكن الفعلي.','tender-consent':'راجع تخصيصك والإيجار والتأمين والفترة. موافقتك تخصك وحدك وتخص النسخة المعروضة، ولا تنشئ عقدًا مشتركًا. معاينة محلية فقط.','disclosure':'راجع البيانات التي اخترت مشاركتها والغرض من استخدامها. لا يتم نشر بيانات أو منح موافقة حقيقية.','company-approval':'راجع نطاق الصلاحية والميزانية والنسخة الحالية. اعتماد الشركة ليس حجزًا أو عقدًا أو صلاحية مالية لشخص آخر. معاينة محلية فقط.'})

